function prepareFeatures(main,sections){const f=sections.find(s=>s.querySelector('h2')?.textContent.includes('Lista de funcionalidades'));if(!f)return;f.id='funcionalidades-terapia';f.classList.add('to-features');const list=f.querySelector('p.font-display');const original=list?[...list.querySelectorAll(':scope>span>span:first-child')].map(x=>x.textContent.trim()).filter(Boolean):[];const groups={'Dentro do seu caderno':['Resumos completos','Flashcards por disciplina','Referências teóricas','Mapas mentais','Planner acadêmico','Calendário e tarefas','Controle de frequência','Provas e trabalhos',...original],...DATA.v6.tagGroups};f.innerHTML=`${heading('Conteúdo, estudo e organização','Todas as funcionalidades do caderno','Mais de 10.000 conteúdos preenchidos para você utilizar o caderno hoje.')}<div class="to-filled-preview"><div class="to-filled-explainer"><h3>Abra o caderno e encontre por onde começar.</h3><p>Os conteúdos e modelos já vêm preenchidos: resumos explicados, perguntas com respostas, referências bibliográficas e exemplos de planejamento. Você começa pelo assunto da aula, pela dúvida da prova ou pelo tema do seu trabalho.</p><ul><li><strong>Para compreender:</strong> conceitos, comparações e situações do cotidiano.</li><li><strong>Para revisar:</strong> flashcards, perguntas e mapas que conectam as ideias.</li><li><strong>Para escrever:</strong> fontes, fichamentos e organização do raciocínio.</li><li><strong>Para personalizar:</strong> acrescente suas anotações e adapte os exemplos à sua rotina.</li></ul></div><article class="to-filled-notebook" aria-label="Exemplo de página preenchida de estudo"><div class="to-notebook-tabs"><span>Resumos</span><span>Revisão</span><span>Fontes</span></div><span class="to-notebook-label">Meu caderno · Terapia Ocupacional</span><h3>Atividade, ocupação e participação</h3><p><mark>O sentido do fazer depende da pessoa e do contexto.</mark> Preparar uma refeição pode envolver autocuidado, trabalho, lazer ou convivência.</p><div class="to-notebook-pair"><div><strong>Atividade</strong><p>Etapas, materiais, tempo e demandas da tarefa.</p></div><div><strong>Ocupação</strong><p>O fazer na vida da pessoa, com história e significado.</p></div></div><h4>Para relacionar</h4><ul><li>Quem escolhe a atividade e por que ela importa?</li><li>Quais barreiras e apoios aparecem no ambiente?</li><li>Como acompanhar a participação no cotidiano?</li></ul><footer>Base de leitura: AOTA (2020) · Cavalcanti e Galvão (2007)</footer></article></div>${Object.entries(groups).map(([label,items])=>`<div class="to-feature-group"><h3>${esc(label)}</h3><div class="to-feature-tags">${[...new Set(items)].map(x=>`<span>${esc(x)}</span>`).join('')}</div></div>`).join('')}`;const offer=main.querySelector('#oferta');if(offer)offer.before(f);}
function enhanceSummaryTables(main){main.querySelectorAll('.to-summary table').forEach(table=>{const labels=[...table.querySelectorAll('th')].slice(0,3).map(x=>x.textContent);table.querySelectorAll('tr').forEach((row,i)=>{if(row.querySelector('td'))row.querySelectorAll('td').forEach((cell,j)=>cell.setAttribute('data-label',labels[j]||''));});});main.querySelectorAll('.to-summary-body>p').forEach((p,i)=>{if(i%3!==0)return;const first=p.firstChild;if(first?.nodeType!==3)return;const text=first.textContent;const match=text.match(/^(.{35,150}?[.!?])\s/);if(!match)return;const mark=document.createElement('mark');mark.textContent=match[1];first.textContent=text.slice(match[1].length);p.prepend(mark);});}
function enhanceOffer(main){const card=main.querySelector('#oferta .purchase-offer-card');if(!card)return;const value=card.querySelector('.purchase-value');const panel=element(`<div class="to-buy-study"><span class="to-eyebrow">Seu caderno no dia a dia</span><h4>Por onde você quer começar?</h4><div class="to-buy-options" role="group" aria-label="Escolher um objetivo de estudo"><button type="button" data-study-use="prova" aria-pressed="true">Provas</button><button type="button" data-study-use="trabalho" aria-pressed="false">Trabalhos</button><button type="button" data-study-use="revisao" aria-pressed="false">Revisões</button></div><p aria-live="polite" data-study-use-text>Comece pelo resumo da matéria, compare os conceitos e responda aos flashcards antes de conferir a explicação.</p></div>`);if(value)value.before(panel);const texts={prova:'Comece pelo resumo da matéria, compare os conceitos e responda aos flashcards antes de conferir a explicação.',trabalho:'Conecte o tema às referências, organize as ideias do fichamento e relacione o argumento às fontes consultadas.',revisao:'Escolha o assunto que precisa retomar, recupere as ideias de memória e use tabelas e mapas para comparar o raciocínio.'};panel.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{panel.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));panel.querySelector('[data-study-use-text]').textContent=texts[b.dataset.studyUse];}));}
