function initPresentation(main){main.querySelectorAll('.to-presentation').forEach(deck=>{deck.querySelectorAll('.to-slide-table table').forEach(table=>{const labels=[...table.querySelectorAll('th')].slice(0,3).map(e=>e.textContent);table.querySelectorAll('tr').forEach(row=>row.querySelectorAll('td').forEach((td,i)=>td.setAttribute('data-label',labels[i]||'')));});const slides=[...deck.querySelectorAll('.to-slide')],prev=deck.querySelector('[data-slide-prev]'),next=deck.querySelector('[data-slide-next]'),buttons=[...deck.querySelectorAll('[data-slide-index]')];let pos=0;function draw(n){pos=Math.max(0,Math.min(slides.length-1,n));slides.forEach((slide,i)=>{slide.hidden=i!==pos;slide.setAttribute('aria-hidden',String(i!==pos));});buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===pos)));prev.disabled=pos===0;next.disabled=pos===slides.length-1;deck.querySelector('[data-slide-status]').textContent=`Slide ${pos+1} de ${slides.length}`;deck.querySelector('progress').value=pos+1;}prev.addEventListener('click',()=>draw(pos-1));next.addEventListener('click',()=>draw(pos+1));buttons.forEach((b,i)=>b.addEventListener('click',()=>draw(i)));deck.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();draw(pos+1);}if(e.key==='ArrowLeft'){e.preventDefault();draw(pos-1);}if(e.key==='Home'){e.preventDefault();draw(0);}if(e.key==='End'){e.preventDefault();draw(slides.length-1);}});draw(0);});}
function clarifyBonus(main){const panel=element(`<aside class="to-extra-flash-bonus" aria-label="Bônus de flashcards"><span class="to-eyebrow">Bônus na compra de hoje</span><h3>Além dos mais de 1.700 flashcards do caderno,<br>ganhe mais 1.500 flashcards de bônus.</h3><p>Uma coleção adicional para revisar conteúdos de <strong>Terapia Ocupacional</strong> cobrados em concursos e provas teóricas da faculdade, sem custo adicional pelo bônus.</p><div class="to-bonus-pair"><span><strong>Mais de 1.700</strong>flashcards que já acompanham o caderno</span><b aria-hidden="true">+</b><span><strong>1.500 extras</strong>flashcards de bônus para ampliar sua revisão</span></div><a href="#oferta">Adquirir o caderno com o bônus · R$ 15,49</a></aside>`);const section=main.querySelector('#fichas-para-revisar');if(section)section.querySelector('header').after(panel);main.querySelectorAll('.offer-included-bonus').forEach(b=>{b.querySelector('h4').textContent='Ganhe mais 1.500 flashcards de bônus.';b.querySelector('p').textContent='Além dos mais de 1.700 flashcards do caderno, receba uma coleção adicional com 1.500 flashcards para concursos e provas teóricas de Terapia Ocupacional, sem custo adicional pelo bônus.';});}
function normalizeQuantities(main){const walker=document.createTreeWalker(main,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){node.textContent=node.textContent.replace(/1[.,]520/g,'1.700').replace(/5[.,]000/g,'2.000').replace(/referências teóricas/g,'referências bibliográficas').replace(/Mais 1[.,]600 flashcards gratuitos\.?/g,'Mais de 1.700 flashcards para estudar.').replace(/1[.,]600 flashcards extras/g,'mais de 1.700 flashcards').replace(/1[.,]600/g,'1.700').replace(/Cartões extras no próprio caderno para ampliar a revisão dos conteúdos e a preparação para provas teóricas, sem custo adicional pelo bônus\./g,'Flashcards no próprio caderno para revisar os assuntos da graduação e preparar suas avaliações.').replace(/com mais de 1\.700 flashcards gratuitos na compra de hoje/g,'com mais de 1.700 flashcards incluídos').replace(/Os mais de 1\.700 flashcards são incluídos gratuitamente no caderno, sem cobrança adicional pelo bônus\./g,'Os flashcards acompanham o caderno no valor apresentado.');}}
function lifePlanner(){return element(`<section id="planner-vida-terapia" class="to-life-planner"><div class="to-life-wrap"><header><span class="to-eyebrow">Da faculdade à vida profissional</span><h2>Seu cotidiano também<br>cabe neste caderno.</h2><p>Estágio, atendimentos, revisões e novos projetos: veja uma página preenchida para conectar os compromissos da semana ao que você quer aprender e realizar.</p></header><div class="to-spiral-page to-planner-page"><span class="to-paper-tape" aria-hidden="true"></span><span class="to-notebook-label">MEU PLANNER · SEMANA EM MOVIMENTO</span><h3>Organizar para cuidar,<br>estudar e seguir em frente.</h3><p class="to-handwritten">Uma prioridade de cada vez, com espaço para toda a sua trajetória.</p><div class="to-planner-cards"><article><span>SEGUNDA · ESTÁGIO</span><h4>Observar e levar à supervisão</h4><ul><li><strong>Antes:</strong> revisar análise de atividades e participação nas AVD.</li><li><strong>Durante:</strong> observar demandas da tarefa, apoios e contexto.</li><li><strong>Depois:</strong> discutir registros e dúvidas com a preceptoria.</li></ul><p class="to-planner-check">✓ Pergunta da semana: como o ambiente facilita a atividade?</p></article><article><span>TERÇA · ATENDIMENTOS</span><h4>Agenda com propósito</h4><ul><li><strong>9h · Caso A:</strong> acompanhar participação na rotina de autocuidado.</li><li><strong>10h30 · Caso B:</strong> conversar sobre rotina, interesses e barreiras do cotidiano.</li><li><strong>Ao finalizar:</strong> organizar registros e pontos para discussão em equipe.</li></ul><p class="to-planner-check">Casos e horários fictícios para demonstrar a organização.</p></article><article><span>QUARTA · CONCURSO E RESIDÊNCIA</span><h4>Revisão que encontra seu foco</h4><ul><li><strong>Assunto:</strong> SUS, integralidade e redes de atenção.</li><li><strong>Prática:</strong> resolver questões e explicar as alternativas.</li><li><strong>Retomada:</strong> anotar a dúvida e agendar nova revisão.</li></ul><p class="to-planner-check">✓ Conectar política pública, território e prática profissional.</p></article><article><span>QUINTA · PESQUISA E PÓS-GRADUAÇÃO</span><h4>Da leitura ao argumento</h4><ul><li><strong>Mestrado ou doutorado:</strong> delimitar a pergunta e o recorte de pesquisa.</li><li><strong>Leitura:</strong> registrar objetivo, método, resultados e limites de um artigo.</li><li><strong>Orientação:</strong> preparar síntese e próximos encaminhamentos.</li></ul><p class="to-planner-check">✓ Relacionar evidências à pergunta que orienta o estudo.</p></article><article><span>SEXTA · PRÁTICA E EQUIPE</span><h4>Dar continuidade ao cuidado</h4><ul><li><strong>Revisar:</strong> objetivos compartilhados e participação nas atividades.</li><li><strong>Articular:</strong> dúvidas e observações para reunião da equipe.</li><li><strong>Planejar:</strong> próximos acompanhamentos e registros.</li></ul><p class="to-planner-check">✓ Manter o foco nas prioridades e escolhas da pessoa.</p></article><article><span>MEU FECHAMENTO DA SEMANA</span><h4>O que fica para a próxima página?</h4><ul><li><strong>Aprendizado:</strong> observar a atividade revela demandas que a teoria ajuda a interpretar.</li><li><strong>Retomar:</strong> autonomia, independência e participação.</li><li><strong>Cuidar de mim:</strong> reservar pausas e tempo de descanso na agenda.</li></ul><p class="to-planner-check">✓ Próxima leitura: avaliação ocupacional em contexto.</p></article></div><p class="to-planner-footer">Rotina acadêmica · Estágio supervisionado · Organização profissional · Concurso · Residência · Pós-graduação</p></div></div></section>`);}
function arrangeFinalSections(main){const order=['abertura-terapia','slides-historia-terapia','disciplinas-terapia','resumos-completos','base-teorica-terapia','semestres-terapia','fichas-para-revisar','planner-vida-terapia','funcionalidades-terapia','oferta'];const footer=[...main.children].find(e=>e.tagName!=='SECTION'&&e.textContent.includes('©'));order.forEach(id=>{const section=document.getElementById(id);if(section){if(footer)main.insertBefore(section,footer);else main.append(section);}});const offer=document.getElementById('oferta');if(!offer)return;const original=offer.querySelector('.offer-final-summary'),buy=offer.querySelector('a[href*="pay.cakto.com.br"]');if(!buy)return;const final=element(`<div class="to-final-compilation"><span class="to-eyebrow">Seu caderno completo</span><h3>Conteúdos para estudar.<br>Um caderno para acompanhar a faculdade.</h3><p>Resumos, flashcards, referências e organização acadêmica em Terapia Ocupacional. Comece pelo assunto que precisa revisar e conecte o conteúdo às suas matérias, aos trabalhos e à prática.</p><div class="to-final-numbers"><span><strong>Mais de 2.600</strong>resumos prontos</span><span><strong>Mais de 1.700</strong>flashcards</span><span><strong>Mais de 2.000</strong>referências bibliográficas</span></div><div class="to-final-tags"><span>Matérias e assuntos</span><span>Mapas de conceitos</span><span>Planejamento acadêmico</span><span>Pesquisa e TCC</span><span>Exemplos preenchidos</span><span>Revisão por conteúdo</span></div><article class="to-spiral-page to-advanced-notebook" aria-label="Resumo de reabilitação neurológica"><span class="to-paper-tape" aria-hidden="true"></span><span class="to-notebook-label">MEU CADERNO · RESUMO PREENCHIDO</span><h4>Reabilitação neurológica<br>e participação no cotidiano</h4><p class="to-handwritten">AVD, autonomia e raciocínio clínico em Terapia Ocupacional</p><p><mark>O objetivo se constrói a partir da vida que a pessoa deseja retomar.</mark> Após um acidente vascular cerebral, uma dificuldade para vestir-se pode envolver movimento, sensibilidade, atenção, planejamento da ação e condições do ambiente. A análise ocupacional relaciona esses fatores às prioridades da pessoa.</p><div class="to-notebook-grid"><div><h5>Perfil ocupacional</h5><ul><li>Investigar rotina anterior, interesses, papéis e rede de apoio.</li><li>Perguntar quais atividades têm maior significado.</li><li>Reconhecer barreiras e facilitadores em casa e na comunidade.</li></ul></div><div><h5>Observar o desempenho</h5><ul><li>Identificar em que etapa da atividade surge a dificuldade.</li><li>Registrar pistas, assistência e recursos utilizados.</li><li>Considerar segurança, fadiga e satisfação com o fazer.</li></ul></div></div><h5>Do objetivo à intervenção</h5><p>Um objetivo funcional descreve a atividade, o contexto e o nível de ajuda esperado. Em um caso acadêmico, “participar do próprio vestir” precisa ser detalhado: escolher a roupa, organizar as peças e realizar as etapas possíveis, com o apoio definido pela avaliação.</p><div class="to-note-flow"><span>Escutar prioridades</span><b aria-hidden="true">→</b><span>Analisar a tarefa</span><b aria-hidden="true">→</b><span>Planejar e acompanhar</span></div><div class="to-notebook-grid"><div><h5>Graduar ou adaptar?</h5><p><strong>Graduar:</strong> modificar a demanda da atividade, como quantidade de etapas ou complexidade. <strong>Adaptar:</strong> reorganizar materiais, ambiente ou modo de fazer. A escolha depende da avaliação e da resposta da pessoa.</p></div><div><h5>Avaliar o resultado</h5><p>Compare o desempenho ao longo do tempo: participação nas etapas, assistência necessária, esforço e satisfação. Um ganho motor isolado não demonstra, por si só, melhora da participação no cotidiano.</p></div></div><p class="to-study-sticky"><strong>Para a prova e o estágio:</strong> autonomia envolve escolhas e decisões; independência se relaciona à realização da atividade com menor necessidade de ajuda. A pessoa pode exercer autonomia mesmo quando precisa de assistência.</p><p class="to-notebook-source">Base de estudo: AOTA. Occupational Therapy Practice Framework: Domain and Process. 4th ed., 2020. WHO. International Classification of Functioning, Disability and Health, 2001.</p></article><div class="to-final-buy"><div><span>Pagamento único</span><strong>R$ 15,49</strong><small>Sem mensalidade</small></div><a href="${esc(buy.getAttribute('href'))}" target="_blank" rel="noopener noreferrer">Adquirir meu caderno · R$ 15,49 <span aria-hidden="true">→</span></a></div><p class="to-final-access">Após a confirmação do pagamento, as orientações de acesso chegam ao e-mail usado na compra.</p></div>`);if(original)original.replaceWith(final);else offer.append(final);}
