 const keepIds=new Set(['abertura-terapia','slides-historia-terapia','resumos-completos','fichas-para-revisar','base-teorica-terapia','disciplinas-terapia','semestres-terapia','planner-vida-terapia','funcionalidades-terapia','oferta']);
 const sections=[...main.children].filter(e=>e.tagName==='SECTION');
 sections.forEach((section,i)=>{const title=section.querySelector('h2')?.textContent.trim()||'';
  const isAgenda=section.classList.contains('agenda-lab');
  const isContact=title==='Contato e suporte.'||section.querySelector('h3')?.textContent.trim()==='Contato e suporte.';
  if(keepIds.has(section.id))return;
  section.remove();
 });
 const agenda=main.querySelector('.agenda-lab');
 if(agenda)agenda.querySelectorAll('.agenda-panels,.agenda-stage-bridge,.agenda-guide').forEach(e=>e.remove());
